const nav = [{id:"overview", label:"Ringkasan", icon:LayoutDashboard},{id:"books",label:"Koleksi buku",icon:BookOpen},{id:"members",label:"Anggota",icon:Users},{id:"shelves",label:"Rak buku",icon:Boxes},{id:"circulation",label:"Sirkulasi",icon:QrCode},{id:"visitors",label:"Pengunjung",icon:DoorOpen},{id:"reports",label:"Laporan",icon:BarChart3}];

function StaffApp() {
  const [user,setUser]=useState(null); const [checking,setChecking]=useState(true); const [view,setViewState]=useState(()=>{try{const v=localStorage.getItem(VIEW_KEY);return nav.some(n=>n.id===v)?v:"overview"}catch{return "overview"}}); const [mobileOpen,setMobileOpen]=useState(false); const [raw,setRaw]=useState({books:[],members:[],shelves:[],transactions:[],reports:{loans:[],incoming:[],missing:[]},stats:{},overdue:{items:[]},reservations:[],stocktake:[]}); const [toast,setToast]=useState(""); const [settings,setSettings]=useState(null); const [account,setAccount]=useState(false);
  // Data offline yang belum tersinkron ditampilkan di atas data tersimpan (stok, transaksi, pinjaman)
  const { queue } = useOffline(); const data = useMemo(()=>applyPendingStaff(raw,queue),[raw,queue]);
  const setView=(v)=>{setViewState(v);try{localStorage.setItem(VIEW_KEY,v)}catch{/* abaikan */}};
  const notify=(text,ms=3200)=>{setToast(text);clearTimeout(window.__perpusToastT);window.__perpusToastT=setTimeout(()=>setToast(""),ms)};
  // Data utama diambil dari server dan disalin ke IndexedDB; saat offline salinan terakhir yang dipakai
  const load = async () => { const g=(u)=>cachedGet(u).catch(()=>undefined); const [stats,books,members,shelves,transactions,reports,cfg,overdue,reservations,stocktake] = await Promise.all([g("/dashboard"),g("/books"),g("/members"),g("/shelves"),g("/transactions"),g("/reports"),g("/settings"),g("/overdue"),g("/reservations"),g("/stocktake")]); if(books===undefined&&members===undefined) throw new Error("no-data"); setRaw(r=>({stats:stats??r.stats,books:books??r.books,members:members??r.members,shelves:shelves??r.shelves,transactions:transactions??r.transactions,reports:reports??r.reports,overdue:overdue??r.overdue,reservations:reservations??r.reservations,stocktake:stocktake??r.stocktake})); if(cfg) setSettings(cfg); };
  useEffect(()=>{cachedGet("/auth/me").then(u=>setUser(u)).catch(()=>{}).finally(()=>setChecking(false));},[]);
  useEffect(()=>{if(user) load().catch(()=>setToast(isOffline()?"Offline: data belum pernah dimuat di perangkat ini":"Data belum dapat dimuat"));},[user]);
  // Sinkron otomatis data offline saat koneksi kembali + pemberitahuan hasilnya
  useEffect(()=>{if(!user)return undefined;startOfflineSync();const onDone=(e)=>{const {synced=[],dropped=[]}=e.detail||{};const parts=[];if(synced.length)parts.push(`${synced.length} data offline berhasil disinkronkan ke server`);if(dropped.length)parts.push(`${dropped.length} data offline dibuang karena ditolak server: ${dropped.map(d=>`${d.meta?.label||"data"} (${d.reason})`).join("; ")}`);if(parts.length)notify(parts.join(" · "),dropped.length?9000:4500);load().catch(()=>{})};window.addEventListener("perpus:sync-done",onDone);return ()=>window.removeEventListener("perpus:sync-done",onDone)},[user]);
  if(checking) return <div className="loading">Membuka perpustakaan...</div>; if(!user) return <Login onLogin={(u)=>{setUser(u);rememberSession(u)}} portal="admin"/>; if(user.role==="siswa") return <Navigate to="/siswa" replace/>;
  const logout=async()=>{await api.post("/auth/logout").catch(()=>{});saveToken(null);forgetSession();setUser(null)};
  return <div className="app-frame" data-user-role={user.role}><aside className={mobileOpen?"sidebar mobile-open":"sidebar"}><div className="side-brand"><img className="logo-img" src={settings?.library_logo || LIBRARY_LOGO} alt="Logo perpustakaan" data-testid="sidebar-library-logo"/><div><strong>RUANG BACA</strong><small>SMANSA ABUNG TENGAH</small></div></div><div className="side-label">MENU UTAMA</div><nav>{nav.map(item=>{const Icon=item.icon;return <button key={item.id} data-testid={`nav-${item.id}-button`} className={view===item.id?"nav-item active":"nav-item"} onClick={()=>{setView(item.id);setMobileOpen(false)}}><Icon size={18}/><span>{item.label}</span>{view===item.id&&<ChevronRight size={15}/>}</button>})}</nav><div className="side-bottom"><button className="nav-item account-btn" data-testid="open-account-button" onClick={()=>{setAccount(true);setMobileOpen(false)}}><KeyRound size={18}/><span>Akun &amp; sandi</span></button><button className="logout" data-testid="logout-button" onClick={logout}><LogOut size={17}/> Keluar</button></div></aside>{mobileOpen&&<div className="sidebar-backdrop" data-testid="sidebar-backdrop" onClick={()=>setMobileOpen(false)}/>}<div className="content"><header className="topbar"><button className="mobile-menu" data-testid="mobile-menu-button" onClick={()=>setMobileOpen(!mobileOpen)}><Menu size={20}/></button><div className="crumb">Perpustakaan <ChevronRight size={14}/><b>{nav.find(n=>n.id===view)?.label}</b></div><div className="top-actions"><ThemeToggle testId="topbar-theme-toggle"/><img className="logo-img" src={settings?.school_logo || SCHOOL_LOGO} alt="Logo sekolah" style={{width:36,height:36,objectFit:"contain"}} data-testid="topbar-school-logo"/><div className="user-chip"><div className="avatar">{user.name[0]}</div><div><b>{user.name}</b><small>{user.role}</small></div></div></div></header><main className="main-area"><div className="page-heading"><div><p className="eyebrow">SMA NEGERI 1 ABUNG TENGAH · {new Date().toLocaleDateString("id-ID",{day:"numeric",month:"long",year:"numeric"})}</p><h2>{view==="overview"?`Selamat datang, ${user.name.split(" ")[0]}.`:nav.find(n=>n.id===view)?.label}</h2></div>{view==="overview"&&<button className="primary" data-testid="quick-circulation-button" onClick={()=>setView("circulation")}><ScanLine size={17}/> Mulai sirkulasi</button>}</div>{view==="overview"&&<Overview data={data} onNavigate={setView} reload={load} notify={notify}/>} {view==="books"&&<Books data={data} reload={load} notify={notify} user={user}/>} {view==="members"&&<Members data={data} reload={load} notify={notify} user={user} settings={settings} setSettings={setSettings}/>} {view==="shelves"&&<ShelvesPage data={data} user={user} reload={load} notify={notify}/>} {view==="circulation"&&<><Circulation data={data} reload={load} notify={notify}/><div style={{marginTop:19}}><ReservationQueue reservations={data.reservations} reload={load} notify={notify}/></div></>} {view==="visitors"&&<Visitors notify={notify} members={data.members}/>} {view==="reports"&&<Reports data={data} settings={settings} notify={notify} user={user} reload={load}/>}</main></div>{account&&<AccountManager user={user} close={()=>setAccount(false)} notify={notify}/>}{toast&&<div className="toast" data-testid="toast-message">{toast}</div>}</div>
}

function Overview({data,onNavigate,reload,notify}) { const s=data.stats; return <><section className="welcome-banner"><div><p className="eyebrow light">PUSAT KENDALI HARI INI</p><h1>Pengetahuan yang terkelola,<br/>sekolah yang <em>bertumbuh.</em></h1><p>Kelola koleksi, pantau aktivitas, dan bantu siswa menemukan buku terbaik.</p><button className="banner-button" data-testid="banner-circulation-button" onClick={()=>onNavigate("circulation")}>Buka sirkulasi <ChevronRight size={16}/></button></div><div className="banner-art"><BookOpen size={88}/><div className="art-line line-one"/><div className="art-line line-two"/></div></section><section className="stat-grid five">{[["Total koleksi",s.books,`eksemplar · ${fmt(s.titles)} judul · ${fmt(s.available)} tersedia`,BookOpen,"blue"],["Anggota aktif",s.members,"siswa & guru",Users,"green"],["Sedang dipinjam",s.borrowed,"eksemplar perlu dipantau",ClipboardList,"orange"],["Buku hilang",s.missing,"eksemplar dari koleksi",Boxes,"red"],["Pengunjung hari ini",s.visitors_today,`${fmt(s.visitors_inside)} masih di dalam`,DoorOpen,"blue"]].map(([label,value,sub,Icon,color])=><div className="stat-card" key={label} data-testid={`stat-${label.replaceAll(" ","-").toLowerCase()}`} onClick={label==="Pengunjung hari ini"?()=>onNavigate("visitors"):undefined} style={label==="Pengunjung hari ini"?{cursor:"pointer"}:undefined}><div className={`stat-icon ${color}`}><Icon size={19}/></div><span>{label}</span><strong>{fmt(value)}</strong><small>{sub}</small></div>)}</section><div className="section-row"><div className="panel activity-panel"><div className="panel-title"><div><p className="eyebrow">AKTIVITAS TERBARU</p><h3>Transaksi terakhir</h3></div><button className="text-button" data-testid="view-all-transactions-button" onClick={()=>onNavigate("reports")}>Lihat semua <ChevronRight size={15}/></button></div>{data.transactions.slice(0,4).map(t=><div className="activity" key={t.id}><div className={`activity-icon ${t.action==="pinjam"?"borrow":"return"}`}>{t.action==="pinjam"?<BookOpen size={16}/>:<ClipboardList size={16}/>}</div><div><b>{t.member_name}</b><span>{t.action==="pinjam"?"meminjam":"mengembalikan"} “{t.book_title}”</span></div><time>{new Date(t.date).toLocaleDateString("id-ID",{day:"numeric",month:"short"})}</time></div>)}</div><div className="panel shortcut-panel"><div className="panel-title"><div><p className="eyebrow">AKSES CEPAT</p><h3>Yang ingin Anda lakukan?</h3></div></div><button className="shortcut" data-testid="shortcut-add-book-button" onClick={()=>onNavigate("books")}><span className="shortcut-icon"><Plus size={18}/></span><div><b>Tambah buku baru</b><small>Perbarui koleksi perpustakaan</small></div><ChevronRight size={16}/></button><button className="shortcut" data-testid="shortcut-add-member-button" onClick={()=>onNavigate("members")}><span className="shortcut-icon green"><Users size={18}/></span><div><b>Daftarkan anggota</b><small>Buat kartu anggota digital</small></div><ChevronRight size={16}/></button><button className="shortcut" data-testid="shortcut-shelves-button" onClick={()=>onNavigate("shelves")}><span className="shortcut-icon orange"><Boxes size={18}/></span><div><b>Susunan rak</b><small>Lihat tata letak koleksi</small></div><ChevronRight size={16}/></button></div></div><div className="overview-row"><OverduePanel overdue={data.overdue} onNavigate={onNavigate}/><ReservationQueue reservations={data.reservations} reload={reload} notify={notify}/></div></>
}

function Books({data,reload,notify,user}) {
  const [search,setSearch]=useState(""); const [show,setShow]=useState(false); const [showIncoming,setShowIncoming]=useState(false); const [statusTarget,setStatusTarget]=useState(null); const [stockTarget,setStockTarget]=useState(null); const [stockVal,setStockVal]=useState(0); const [qrTarget,setQrTarget]=useState(null); const [bulkQr,setBulkQr]=useState(null); const [stockErr,setStockErr]=useState(""); const [editing,setEditing]=useState(null);
  const staff=user.role!=="siswa";
  const emptyForm = {title:"",author:"",category:"Umum",shelf:"R-01",isbn:"",cover:"",stock:1};
  const [form,setForm]=useState(emptyForm);
  const filtered=data.books.filter(b=>`${b.title} ${b.author} ${b.category} ${b.id}`.toLowerCase().includes(search.toLowerCase()));
  const add=async(e)=>{e.preventDefault();try{const {data:r}=await api.post("/books",{...form,stock:Number(form.stock)||1});setShow(false);setForm(emptyForm);reload();notify(r.merged?`Judul sudah ada — stok "${r.title}" bertambah ${r.added} menjadi ${r.stock}`:"Buku berhasil ditambahkan")}catch(err){notify(err.response?.data?.detail?.[0]?.msg||err.response?.data?.detail||"Gagal menambah buku")}};
  const openAdd=()=>{setEditing(null);setForm({...emptyForm,shelf:data.shelves[0]?.id||"R-01"});setShow(true)};
  const openEdit=(b)=>{setEditing(b);setForm({title:b.title,author:b.author,category:b.category||"Umum",shelf:b.shelf,isbn:b.isbn||"",cover:b.cover||"",stock:b.stock});setShow(true)};
  const saveEdit=async(e)=>{e.preventDefault();try{const {stock,...body}=form;const {data:r}=await api.put(`/books/${editing.id}`,body);setShow(false);setEditing(null);setForm(emptyForm);reload();notify(`Data buku "${r.title}" diperbarui`)}catch(err){notify(err.response?.data?.detail?.[0]?.msg||err.response?.data?.detail||"Gagal menyimpan perubahan")}};
  const openStock=(b)=>{setStockTarget(b);setStockVal(b.stock);setStockErr("")};
  const saveStock=async(e)=>{e.preventDefault();setStockErr("");try{const {data:r}=await api.patch(`/books/${stockTarget.id}/stock`,{stock:Number(stockVal)});setStockTarget(null);reload();notify(`Stok "${r.title}" kini ${r.stock} eksemplar`)}catch(err){setStockErr(err.response?.data?.detail||"Gagal menyimpan stok")}};
  const remove=async(id)=>{if(window.confirm("Hapus buku ini dari koleksi?")){await api.delete(`/books/${id}`);reload();notify("Buku dihapus")}};
  const markLost=(b)=>setStatusTarget({book:b,mode:"lost"});
  const markFound=(b)=>setStatusTarget({book:b,mode:"found"});
  return <><div className="toolbar"><div className="searchbox"><Search size={17}/><input data-testid="book-search-input" placeholder="Cari judul, penulis, kode, atau kategori..." value={search} onChange={e=>setSearch(e.target.value)}/></div>{staff&&<div className="toolbar-buttons"><button className="secondary" data-testid="bulk-qr-open-button" onClick={()=>setBulkQr({})}><QrCode size={17}/> Cetak QR massal</button><button className="secondary" data-testid="incoming-book-button" onClick={()=>setShowIncoming(true)}><PackagePlus size={17}/> Buku masuk</button><button className="primary" data-testid="add-book-button" onClick={openAdd}><Plus size={17}/> Tambah buku</button></div>}</div><div className="panel table-panel"><div className="panel-title"><div><p className="eyebrow">INVENTARIS KOLEKSI</p><h3>{filtered.length} buku dalam katalog</h3></div><span className="soft-badge"><Boxes size={14}/> {data.shelves.length} rak aktif</span></div><div className="table-wrap"><table><thead><tr><th>BUKU</th><th>KATEGORI</th><th>RAK</th><th>STOK</th><th>STATUS</th><th></th></tr></thead><tbody><ShowMore items={filtered} colSpan={6}>{(vis)=>vis.map(b=><tr key={b.id} data-testid={`book-row-${b.id}`}><td><div className="book-cell"><div className="book-cover">{b.cover?<img src={b.cover} alt={b.title} loading="lazy" decoding="async"/>:<BookOpen size={18}/>}</div><div><b>{b.title}</b><span>{b.author} · {b.id}</span></div></div></td><td>{b.category}</td><td><span className="shelf-tag">{b.shelf}</span></td><td><StockCell b={b}/></td><td><span className={`status ${b.status.toLowerCase()}`} data-testid={`book-status-${b.id}`}>{b.status}</span></td><td>{staff&&<div className="row-actions"><button className="ok-icon" title="QR buku" data-testid={`qr-book-${b.id}-button`} onClick={()=>setQrTarget(b)}><QrCode size={15}/></button><button className="ok-icon" title="Edit buku" data-testid={`edit-book-${b.id}-button`} onClick={()=>openEdit(b)}><Pencil size={15}/></button><button className="ok-icon" title="Atur stok" data-testid={`stock-book-${b.id}-button`} onClick={()=>openStock(b)}><Layers size={15}/></button>{b.lost>0&&<button className="ok-icon" title="Tandai 1 eksemplar ditemukan" data-testid={`found-book-${b.id}-button`} onClick={()=>markFound(b)}><RotateCcw size={15}/></button>}{b.available>0&&<button className="warn-icon" title="Lapor 1 eksemplar hilang" data-testid={`lost-book-${b.id}-button`} onClick={()=>markLost(b)}><AlertTriangle size={16}/></button>}<button className="danger-icon" title="Hapus" data-testid={`delete-book-${b.id}-button`} onClick={()=>remove(b.id)}><Trash2 size={16}/></button></div>}</td></tr>)}</ShowMore></tbody></table></div></div>{show&&<Modal title={editing?"Edit buku":"Tambah buku baru"} close={()=>{setShow(false);setEditing(null)}}><form onSubmit={editing?saveEdit:add} className="modal-form" data-testid={editing?"edit-book-form":"add-book-form"}>{editing&&<div className="soft-badge" style={{width:"fit-content"}}><BookOpen size={14}/> {editing.id} · stok {editing.available}/{editing.stock} · QR tetap sama</div>}<PhotoBox value={form.cover} onChange={(v)=>setForm({...form,cover:v})} label="Sampul buku" testId="book-cover-box"/>{[["title","Judul buku"],["author","Penulis"],["isbn","ISBN (opsional)"]].map(([key,label])=><label key={key}>{label}<input data-testid={`book-${key}-input`} required={key!=="isbn"} value={form[key]} onChange={e=>setForm({...form,[key]:e.target.value})}/></label>)}{!editing&&<><label>Jumlah stok (eksemplar)<input data-testid="book-stock-input" type="number" min={1} max={1000} required value={form.stock} onChange={e=>setForm({...form,stock:e.target.value})}/></label><p className="muted" style={{fontSize:11,marginTop:-6}}>Jika judul &amp; penulis sudah ada, stoknya akan ditambahkan ke buku yang sama (satu judul, satu QR).</p></>}<label>Kategori<select data-testid="book-category-input" value={form.category} onChange={e=>setForm({...form,category:e.target.value})}>{[...new Set(["Umum","Sastra","Sains","Pelajaran",...data.books.map(b=>b.category).filter(Boolean)])].map(c=><option key={c}>{c}</option>)}</select></label><label>Rak<select data-testid="book-shelf-input" value={form.shelf} onChange={e=>setForm({...form,shelf:e.target.value})}>{data.shelves.map(s=><option key={s.id} value={s.id}>{s.id} · {s.name}</option>)}</select></label><button className="primary full" data-testid="save-book-button">{editing?"Simpan perubahan":"Simpan buku"}</button></form></Modal>}{showIncoming&&<IncomingForm shelves={data.shelves} close={()=>setShowIncoming(false)} onSaved={(d)=>{reload();notify(d.merged?`Stok "${d.title}" bertambah ${d.quantity} menjadi ${d.stock_after}`:`${d.quantity} eksemplar "${d.title}" masuk ke koleksi`)}}/>}{stockTarget&&<Modal title="Atur stok buku" close={()=>setStockTarget(null)}><form className="modal-form" onSubmit={saveStock} data-testid="stock-form"><div className="lost-banner ok"><BookOpen size={20}/><div><b>{stockTarget.title}</b><small>{stockTarget.author} · {stockTarget.id} · {stockTarget.borrowed} sedang dipinjam · {stockTarget.lost||0} hilang</small></div></div><label>Jumlah eksemplar dimiliki<div className="stock-input-row"><button type="button" className="secondary" data-testid="stock-minus" onClick={()=>setStockVal(v=>Math.max(0,Number(v)-1))}><Minus size={16}/></button><input data-testid="stock-value-input" type="number" min={0} value={stockVal} onChange={e=>setStockVal(e.target.value)}/><button type="button" className="secondary" data-testid="stock-plus" onClick={()=>setStockVal(v=>Number(v)+1)}><Plus size={16}/></button></div></label><p className="muted" style={{fontSize:12}}>Tersedia di rak setelah disimpan: <b>{Math.max(0,Number(stockVal)-(stockTarget.borrowed||0))}</b>. Stok berkurang/bertambah otomatis saat buku dipinjam &amp; dikembalikan.</p>{stockErr&&<div className="error" data-testid="stock-error">{stockErr}</div>}<button className="primary full" data-testid="save-stock-button">Simpan stok</button></form></Modal>}{qrTarget&&<Modal title="QR buku" close={()=>setQrTarget(null)}><div className="qr-label" data-testid="book-qr-label"><img src={`https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(qrTarget.id)}&margin=0&color=0f2745`} alt={`QR ${qrTarget.id}`}/><b>{qrTarget.title}</b><small>{qrTarget.author} · {qrTarget.id} · Rak {qrTarget.shelf} · {qrTarget.stock} eksemplar</small></div><p className="muted" style={{fontSize:12}}>Satu QR untuk semua eksemplar judul ini. Tempel pada setiap eksemplar.</p><button className="primary full" data-testid="print-book-qr-button" onClick={()=>{const w=window.open("","_blank");if(!w)return;w.document.write(`<html><head><title>QR ${qrTarget.id}</title></head><body style="font-family:sans-serif;text-align:center;padding:30px"><img src="https://api.qrserver.com/v1/create-qr-code/?size=220x220&data=${encodeURIComponent(qrTarget.id)}&margin=0" onload="window.print()"/><h3>${qrTarget.title.replace(/</g,"&lt;")}</h3><p>${qrTarget.id} · Rak ${qrTarget.shelf}</p></body></html>`);w.document.close()}}><Printer size={16}/> Cetak label QR</button><button className="secondary full" style={{marginTop:8}} data-testid="print-book-qr-copies-button" onClick={()=>{const b=qrTarget;setQrTarget(null);setBulkQr({ids:[b.id],copies:"stok"})}}><QrCode size={16}/> Cetak {qrTarget.stock||1} label (sesuai eksemplar)</button></Modal>}{bulkQr&&<BulkBookQrPrint books={data.books} shelves={data.shelves} initialIds={bulkQr.ids||null} initialCopies={bulkQr.copies||"satu"} close={()=>setBulkQr(null)}/>}{statusTarget&&<LostBookModal book={statusTarget.book} mode={statusTarget.mode} user={user} close={()=>setStatusTarget(null)} onDone={()=>{reload();notify(statusTarget.mode==="lost"?"Buku ditandai hilang & masuk laporan":"Buku dipulihkan ke koleksi")}}/>}</>
}

function StockCell({b}) { const pct=b.stock?Math.round((b.available/b.stock)*100):0; return <div className="stock-cell" data-testid={`book-stock-${b.id}`}><b>{b.available}/{b.stock} tersedia</b><div className={`stock-meter ${b.available===0?"empty":pct<=34?"low":""}`}><div style={{width:`${pct}%`}}/></div><small>{b.borrowed} dipinjam{b.lost?` · ${b.lost} hilang`:""}</small></div> }

function Members({data,reload,notify,user,settings,setSettings}) {
  const [show,setShow]=useState(false); const [selected,setSelected]=useState(data.members[0]); const [design,setDesign]=useState(false); const [bulk,setBulk]=useState(false); const [editTarget,setEditTarget]=useState(null); const [bulkDel,setBulkDel]=useState(false); const [imp,setImp]=useState(false); const [promote,setPromote]=useState(false); const [promoteForm,setPromoteForm]=useState({from_class:"",to_class:""}); const [promoting,setPromoting]=useState(false); const [accTarget,setAccTarget]=useState(null); const [cardSide,setCardSide]=useState("depan"); const [printOne,setPrintOne]=useState(null);
  const staff=user.role!=="siswa";
  useEffect(()=>{if(!selected && data.members[0])setSelected(data.members[0])},[data.members]);
  const emptyForm = EMPTY_MEMBER;
  const [form,setForm]=useState(emptyForm);
  const errMsg=(err,fb)=>{const d=err.response?.data?.detail;return Array.isArray(d)?(d[0]?.msg||fb):(d||fb)};
  const add=async(e)=>{e.preventDefault();try{const {data:m}=await api.post("/members",form);setShow(false);setForm(emptyForm);setSelected(m);reload();notify(isGuru(m)?`Guru "${m.name}" berhasil ditambahkan`:"Anggota berhasil ditambahkan")}catch(err){notify(errMsg(err,"Gagal menambah anggota"))}};
  const openEdit=(m)=>{setForm(memberToForm(m));setEditTarget(m)};
  const saveEdit=async(e)=>{e.preventDefault();try{const {data:u}=await api.put(`/members/${editTarget.id}`,form);setEditTarget(null);setForm(emptyForm);if(selected?.id===u.id)setSelected(u);reload();notify("Data anggota diperbarui")}catch(err){notify(errMsg(err,"Gagal menyimpan perubahan"))}};
  const promoteClasses=()=>classCounts.filter(([c])=>c!=="Guru");
  const removeMember=async(m)=>{if(window.confirm(`Hapus anggota "${m.name}" (${m.class_name})? Tindakan ini tidak dapat dibatalkan.`)){await api.delete(`/members/${m.id}`);if(selected?.id===m.id)setSelected(null);reload();notify("Anggota dihapus")}};
  const doBulkDelete=async(className,count)=>{if(!window.confirm(`Hapus SEMUA ${count} anggota kelas "${className}"? Tindakan ini tidak dapat dibatalkan.`))return;try{const {data:r}=await api.post("/members/bulk-delete",{class_name:className});setBulkDel(false);setSelected(null);reload();notify(`${r.deleted} anggota kelas ${className} dihapus`)}catch(e){notify(e.response?.data?.detail||"Gagal menghapus")}};
  const doPromote=async(e)=>{e.preventDefault();const from_class=promoteForm.from_class.trim();const to_class=promoteForm.to_class.trim();if(!from_class||!to_class)return notify("Pilih kelas asal dan isi kelas tujuan");if(from_class===to_class)return notify("Kelas asal dan tujuan tidak boleh sama");setPromoting(true);try{const {data:r}=await api.post("/members/promote",{from_class,to_class});setPromote(false);setPromoteForm({from_class:"",to_class:""});reload();notify(`${r.moved} anggota naik dari "${from_class}" ke "${to_class}"`)}catch(err){notify(err.response?.data?.detail||"Gagal memproses naik kelas")}finally{setPromoting(false)}};
  const saveDesign=async(s)=>{const {data:d}=await api.put("/settings",s);setSettings(d);notify("Desain kartu disimpan")};
  const classCounts=Object.entries(data.members.reduce((a,m)=>{const k=m.class_name||"(Tanpa kelas)";a[k]=(a[k]||0)+1;return a},{})).sort((a,b)=>a[0].localeCompare(b[0]));
  return <><div className="toolbar"><div><p className="eyebrow">DIREKTORI SEKOLAH</p><h3 className="toolbar-title">{data.members.length} anggota terdaftar</h3></div>{staff&&<div className="toolbar-buttons"><button className="secondary" data-testid="import-members-open-button" onClick={()=>setImp(true)}><Upload size={17}/> Impor</button><button className="secondary" data-testid="bulk-delete-open-button" onClick={()=>setBulkDel(true)}><UserX size={17}/> Hapus massal</button><button className="secondary" data-testid="promote-open-button" onClick={()=>setPromote(true)}><GraduationCap size={17}/> Naik kelas</button><button className="primary" data-testid="add-member-button" onClick={()=>setShow(true)}><Plus size={17}/> Tambah anggota</button></div>}</div><div className="member-layout"><div className="panel member-list"><div className="panel-title"><h3>Daftar anggota</h3></div><MemberClassList members={data.members} renderRow={m=><div className={selected?.id===m.id?"member-row selected":"member-row"} data-testid={`member-${m.id}-row`} key={m.id}><button className="member-row-main" data-testid={`member-${m.id}-button`} onClick={()=>setSelected(m)}><div className={`avatar large${m.photo?"":" no-photo"}`}>{m.photo?<img src={m.photo} alt={m.name}/>:m.name[0]}</div><div className="member-row-text"><b>{m.name}</b>{isGuru(m)?<span data-testid={`member-${m.id}-type`}><em className="type-tag guru">Guru</em>{m.subject?`Mapel: ${m.subject}`:"Guru"}</span>:<span>{m.student_id} · {m.class_name}</span>}{!m.photo&&<em className="no-photo-tag" data-testid={`member-${m.id}-no-photo`}><CameraOff size={11}/> Belum upload foto</em>}</div></button>{staff&&<div className="member-row-actions"><button className="ok-icon" title="Akun login anggota" data-testid={`account-member-${m.id}-button`} onClick={()=>setAccTarget(m)}><KeyRound size={15}/></button><button className="ok-icon" title="Edit anggota" data-testid={`edit-member-${m.id}-button`} onClick={()=>openEdit(m)}><Pencil size={15}/></button><button className="danger-icon" title="Hapus anggota" data-testid={`delete-member-${m.id}-button`} onClick={()=>removeMember(m)}><Trash2 size={15}/></button></div>}</div>}/></div><div className="member-detail"><div className="member-card-wrap"><p className="eyebrow">PRATINJAU KARTU DIGITAL</p><div className="mode-switch side-switch" data-testid="member-card-side-switch">{[["depan","Depan"],["belakang","Belakang"]].map(([id,l])=><button key={id} type="button" data-testid={`member-card-side-${id}`} className={cardSide===id?"selected":""} onClick={()=>setCardSide(id)}>{l}</button>)}</div>{cardSide==="depan"?<MemberCard member={selected} settings={settings}/>:<div id="print-card"><MemberCardBack settings={settings}/></div>}<div className="card-actions"><button className="secondary print-btn" data-testid="print-member-card-button" onClick={()=>setPrintOne(cardSide)}><CreditCard size={17}/> Cetak kartu</button><CardHDButton getEl={()=>document.querySelector("#print-card.id-card, #print-card .id-card-back")} member={selected} notify={notify} testId="card-png-hd" label="Unduh PNG HD"/>{staff&&<button className="secondary print-btn" data-testid="design-card-button" onClick={()=>setDesign(true)}><Palette size={17}/> Desain kartu</button>}{staff&&<button className="secondary print-btn" data-testid="bulk-print-button-open" onClick={()=>setBulk("semua")}><Printer size={17}/> Cetak massal</button>}</div></div><MemberHistory member={selected} refreshKey={data.transactions.length}/></div></div>{printOne&&selected&&<SingleCardPrint member={selected} settings={settings} side={printOne} onDone={()=>setPrintOne(null)}/>}{show&&<Modal title="Daftarkan anggota baru" close={()=>{setShow(false);setForm(emptyForm)}}><MemberForm form={form} setForm={setForm} onSubmit={add} prefix="member" submitLabel={form.member_type==="guru"?"Simpan anggota guru":"Simpan anggota"} submitTestId="save-member-button" photoTestId="member-photo-box" notify={notify}/></Modal>}{design&&<CardDesigner settings={settings} member={selected} onSave={saveDesign} close={()=>setDesign(false)}/>}{bulk!==false&&<BulkCardPrint members={data.members} settings={settings} initialClass={bulk} notify={notify} close={()=>setBulk(false)}/>}{editTarget&&<Modal title="Edit data anggota" close={()=>{setEditTarget(null);setForm(emptyForm)}}><MemberForm form={form} setForm={setForm} onSubmit={saveEdit} prefix="edit-member" submitLabel="Simpan perubahan" submitTestId="save-edit-member-button" photoTestId="edit-member-photo-box" photoLocked={user.role!=="admin"&&!!editTarget.photo} notify={notify}/></Modal>}{bulkDel&&<Modal title="Hapus massal per kelas" close={()=>setBulkDel(false)}><p className="account-hint">Pilih kelas untuk menghapus seluruh anggotanya sekaligus. Pesanan aktif akan dibatalkan; riwayat transaksi tetap tersimpan.</p><div className="bulk-del-list">{classCounts.length===0&&<p className="account-hint">Belum ada anggota.</p>}{classCounts.map(([cls,count])=><button type="button" className="bulk-del-class" key={cls} data-testid={`bulk-del-class-${cls}`} onClick={()=>doBulkDelete(cls,count)}><span><b>{cls}</b><small>Klik untuk menghapus semua anggota kelas ini</small></span><span className="bulk-del-count">{count} anggota</span></button>)}</div></Modal>}{imp&&<MemberImport close={()=>setImp(false)} onDone={()=>reload()} notify={notify}/>}{accTarget&&<MemberAccount member={accTarget} close={()=>setAccTarget(null)} notify={notify}/>}{promote&&<Modal title="Naik kelas anggota" close={()=>{setPromote(false);setPromoteForm({from_class:"",to_class:""})}}><form onSubmit={doPromote} className="modal-form"><p className="account-hint" style={{marginTop:0}}>Pindahkan seluruh anggota dari satu kelas ke kelas berikutnya. Cocok untuk pergantian tahun ajaran. NIS, foto, dan riwayat tetap tersimpan. Anggota guru tidak ikut naik kelas.</p><label>Kelas asal<select data-testid="promote-from-select" required value={promoteForm.from_class} onChange={e=>setPromoteForm({...promoteForm,from_class:e.target.value})}><option value="">— Pilih kelas asal —</option>{promoteClasses().map(([cls,count])=><option key={cls} value={cls}>{cls} ({count} anggota)</option>)}</select></label><label>Kelas tujuan<input data-testid="promote-to-input" required placeholder="mis. XI IPA 2" value={promoteForm.to_class} onChange={e=>setPromoteForm({...promoteForm,to_class:e.target.value})}/></label>{classCounts.length===0&&<p className="account-hint">Belum ada anggota untuk dinaikkan.</p>}<button className="primary full" data-testid="save-promote-button" disabled={promoting}>{promoting?"Memproses...":"Naikkan kelas"}</button></form></Modal>}</>
}
function Circulation({data,reload,notify}) {
  const [mode,setMode]=useState("pinjam"); const [member,setMember]=useState(""); const [book,setBook]=useState("");
  const [scan,setScan]=useState(false); const [scanTarget,setScanTarget]=useState("member");
  const [manual,setManual]=useState("");
  const openLoans=(data.reports?.loans||[]).filter(l=>l.status==="Dipinjam");
  const memberLoanIds=new Set(openLoans.filter(l=>l.member_id===member).map(l=>l.book_id));
  const choices=data.books.filter(b=>mode==="kembali"?(member?memberLoanIds.has(b.id):b.borrowed>0):b.available>0);
  const resolveCode=(code)=>{const c=code.trim().toUpperCase();const m=data.members.find(x=>x.id.toUpperCase()===c||x.student_id?.toUpperCase()===c);const b=data.books.find(x=>x.id.toUpperCase()===c||x.isbn?.toUpperCase()===c);if(m){setMember(m.id);notify(`Anggota: ${m.name}`);return true}if(b){setBook(b.id);notify(`Buku: ${b.title}`);return true}notify("Kode tidak ditemukan");return false};
  const [saving,setSaving]=useState(false);
  // Layar hasil + bunyi (Web Audio): pinjam = 2 nada naik, kembali = 3 nada turun, gagal = dengung rendah
  const [result,setResult]=useState(null);
  const memberInfo=(m)=>m?(isGuru(m)?`Guru${m.subject?` · ${m.subject}`:""}`:[m.class_name,m.student_id].filter(Boolean).join(" · ")):"";
  const succeed=(offline=false)=>{const m=data.members.find(x=>x.id===member);const b=data.books.find(x=>x.id===book);scanSound(mode==="pinjam"?"masuk":"keluar");setResult({ok:true,mode,offline,member:m?.name||"-",memberInfo:memberInfo(m),book:b?.title||"-"});setMember("");setBook("")};
  const fail=(message)=>{scanSound("error");setResult({ok:false,mode,message});notify(message)};
  // Offline: dicek dengan data tersimpan, lalu disimpan di perangkat (IndexedDB) dan dikirim otomatis saat online
  const saveOffline=async()=>{const m=data.members.find(x=>x.id===member);const b=data.books.find(x=>x.id===book);if(!m||!b)return fail("Anggota atau buku tidak ditemukan di data tersimpan");const open=openLoans.some(l=>l.member_id===member&&l.book_id===book);if(mode==="pinjam"){if(b.available<=0)return fail(`Stok "${b.title}" habis`);if(open)return fail("Anggota ini masih meminjam buku yang sama")}else if(!open)return fail("Anggota ini tidak sedang meminjam buku ini");try{await enqueue("tx",{member_id:member,book_id:book,action:mode},{label:`${m.name} ${mode==="pinjam"?"meminjam":"mengembalikan"} "${b.title}"`,member_name:m.name,class_name:m.class_name||"",book_title:b.title});notify(`Offline · ${mode==="pinjam"?"peminjaman":"pengembalian"} disimpan di perangkat dan akan disinkronkan otomatis`,4500);succeed(true)}catch(e){fail("Gagal menyimpan data offline di perangkat ini")}};
  const submit=async()=>{if(!member||!book)return fail("Pilih anggota dan buku terlebih dahulu");if(saving)return;if(isOffline())return saveOffline();setSaving(true);try{await api.post("/transactions",{member_id:member,book_id:book,action:mode});reload();const b=data.books.find(x=>x.id===book);notify(mode==="pinjam"?`Peminjaman tercatat · sisa stok ${b?b.available-1:"-"}`:`Pengembalian tercatat · stok tersedia ${b?b.available+1:"-"}`);succeed(false)}catch(e){if(isNetErr(e))await saveOffline();else fail(e.response?.data?.detail||"Transaksi gagal")}finally{setSaving(false)}};
  const closeResult=useCallback(()=>setResult(null),[]);
  const openScanner=(t)=>{setScanTarget(t);setScan(true)};
  const applyManual=()=>{if(!manual.trim())return;resolveCode(manual);setManual("")};
  return <><OfflineBar testId="offline-bar-circulation" kinds={["tx"]}/><div className="circulation-grid"><div className="panel circulation-panel"><div className="mode-switch"><button data-testid="borrow-mode-button" className={mode==="pinjam"?"selected":""} onClick={()=>setMode("pinjam")}>Pinjam buku</button><button data-testid="return-mode-button" className={mode==="kembali"?"selected":""} onClick={()=>setMode("kembali")}>Kembalikan</button></div>
    <div className="scanner-box"><ScanLine size={40}/><h3>Pindai QR anggota &amp; buku</h3><p>Bisa menggunakan kamera HP, atau input kode manual di bawah.</p><div className="scan-buttons"><button className="secondary" data-testid="scan-member-button" onClick={()=>openScanner("member")}><QrCode size={16}/> Scan Anggota</button><button className="secondary" data-testid="scan-book-button" onClick={()=>openScanner("book")}><QrCode size={16}/> Scan Buku</button></div></div>
    <div className="manual-row"><input placeholder="Ketik/tempel kode (MB-xxx atau BK-xxx)" value={manual} onChange={e=>setManual(e.target.value)} data-testid="manual-code-input" onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();applyManual()}}}/><button className="secondary" data-testid="apply-manual-code-button" onClick={applyManual}>Terapkan</button></div>
    <div className="or-line"><span>atau cari dari daftar</span></div>
    <div className="field-label">Anggota<MemberSearch members={data.members} value={member} onChange={setMember}/></div>
    <div className="field-label">Buku<BookSearch books={choices} value={book} onChange={setBook} selectedBook={data.books.find(x=>x.id===book)} emptyText={mode==="kembali"&&member?"Anggota ini tidak sedang meminjam buku":mode==="kembali"?"Tidak ada buku yang sedang dipinjam":"Tidak ada buku yang tersedia"}/></div>{book&&(()=>{const b=data.books.find(x=>x.id===book);return b?<div className="soft-badge" style={{marginTop:10,width:"fit-content"}} data-testid="circulation-stock-info"><BookOpen size={14}/> Stok "{b.title}": {b.available} dari {b.stock} tersedia → setelah {mode==="pinjam"?"dipinjam":"dikembalikan"}: {mode==="pinjam"?b.available-1:b.available+1}</div>:null})()}
    <button className="primary full" data-testid="submit-circulation-button" onClick={submit} disabled={saving}>{mode==="pinjam"?"Catat peminjaman":"Catat pengembalian"} <ChevronRight size={17}/></button></div>
    <div className="panel today-panel"><div className="panel-title"><div><p className="eyebrow">HARI INI</p><h3>Aktivitas sirkulasi</h3></div><span className="live-dot">LIVE</span></div>{data.transactions.slice(0,7).map(t=><div className="mini-transaction" key={t.id} data-testid={t.pending?`pending-tx-${t.id}`:undefined}><div className={`activity-icon ${t.action==="pinjam"?"borrow":"return"}`}>{t.action==="pinjam"?<BookOpen size={15}/>:<ClipboardList size={15}/>}</div><div><b>{t.member_name}{t.pending&&<PendingTag/>}</b><span>{t.book_title}</span></div><small>{t.action}</small></div>)}</div>
  </div>
  {scan && <QRScanner onDetect={(code)=>{setScan(false);resolveCode(code)}} onClose={()=>setScan(false)}/>}<CirculationResult result={result} onClose={closeResult}/></>
}

function ShelvesPage({data,user,reload,notify}) {
  const [stock,setStock]=useState(false); const last=data.stocktake?.[0];
  return <>{user.role!=="siswa"&&<div className="shelves-toolbar"><div className="stock-history">{last?<span data-testid="last-stocktake">Opname terakhir: Rak {last.shelf} · {fmtDate(last.date)} · {last.scanned_count} ada / {last.unscanned_count} tidak terpindai</span>:<span>Belum pernah stok opname</span>}</div>{!stock&&<button className="primary" data-testid="start-stocktake-button" onClick={()=>setStock(true)}><ClipboardCheck size={17}/> Mulai stok opname</button>}</div>}
  {stock&&<div style={{marginBottom:20}}><Stocktake data={data} user={user} reload={reload} notify={notify} close={()=>setStock(false)}/></div>}
  <ShelfManager data={data} user={user} reload={reload} notify={notify}/></>
}

function Reports({data,settings,notify,user,reload}) {
  const [tab,setTab]=useState("ringkasan"); const [picked,setPicked]=useState([]); const [purgeOpen,setPurgeOpen]=useState(false); const [visitsTick,setVisitsTick]=useState(0); const [period,setPeriod]=useState("semua"); const [downloading,setDownloading]=useState(false); const reportData=data.reports||{loans:[],incoming:[],missing:[]};
  const [visitsRaw,setVisits]=useState([]); const { queue } = useOffline();
  // Riwayat pengunjung disalin ke IndexedDB -> tetap bisa dilihat offline; catatan offline ikut ditampilkan
  const visits=useMemo(()=>{const rows=applyPendingVisits(visitsRaw,queue);if(rows===visitsRaw)return rows;const nowD=new Date();return rows.filter(r=>!r.pending||period==="semua"||(period==="harian"?new Date(r.check_in).toDateString()===nowD.toDateString():new Date(r.check_in).getMonth()===nowD.getMonth()))},[visitsRaw,queue,period]);
  useEffect(()=>{if(tab==="kunjungan")cachedGet("/visits/history",{period}).then(setVisits).catch(()=>notify?.(isOffline()?"Offline: laporan pengunjung periode ini belum pernah dibuka di perangkat ini":"Data pengunjung belum dapat dimuat"))},[tab,period,visitsTick,queue.length]);
  useEffect(()=>{setPicked([])},[tab,period]);
  const canPurge=user?.role==="admin"&&PURGE_TABS.includes(tab);
  const now=new Date();
  const inPeriod=(d)=>{if(!d)return true;const dt=new Date(d);if(period==="harian")return dt.toDateString()===now.toDateString();if(period==="bulanan")return dt.getMonth()===now.getMonth()&&dt.getFullYear()===now.getFullYear();return true};
  const source=tab==="transaksi"?(reportData.loans||[]):tab==="masuk"?reportData.incoming:tab==="hilang"?reportData.missing:tab==="kunjungan"?visits:[];
  const rows=tab==="kunjungan"?visits:(tab==="statistik"||tab==="peringkat"||tab==="peringkat-pinjam"||tab==="ringkasan")?[]:source.filter(r=>inPeriod(r.date));
  const totalIn=reportData.incoming.reduce((a,r)=>a+(r.quantity||0),0); const stillLost=reportData.missing.filter(r=>r.status==="Hilang").length;
  const [lbAudience,setLbAudience]=useState("siswa");
  const periodLabel=period==="harian"?"Hari ini":period==="bulanan"?"Bulan ini":"Semua waktu";
  const fmtTime=(d)=>d?new Date(d).toLocaleString("id-ID",{day:"numeric",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit",timeZone:"Asia/Jakarta"}):"-";
  const download=async(ext="pdf",type=tab,per=period,extra={})=>{setDownloading(ext);try{const res=await api.get(`/reports/export.${ext}`,{params:{type,period:per,...extra},responseType:"blob"});const url=URL.createObjectURL(res.data);const a=document.createElement("a");a.href=url;a.download=`laporan-${type}${extra.audience==="guru"?"-guru":""}-${per}.${ext}`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);notify?.(`Laporan ${ext==="pdf"?"PDF":"Excel"} berhasil diunduh`)}catch(e){notify?.("Gagal mengunduh laporan")}finally{setDownloading(false)}};
  const heads=tab==="transaksi"?["ANGGOTA","KELAS","BUKU","TGL PINJAM","TGL KEMBALI","STATUS"]:tab==="kunjungan"?["PENGUNJUNG","KELAS / ASAL","KEPERLUAN","MASUK","KELUAR","DURASI","CARA KELUAR"]:tab==="masuk"?["NO","JUDUL BUKU","PENULIS","JUMLAH","SUMBER","TANGGAL"]:["JUDUL BUKU","KETERANGAN","TANGGAL","STATUS"];
  const cells=(r,i=0)=>tab==="transaksi"?[<b>{r.member_name}</b>,r.class_name||"-",<><b>{r.book_title}</b><div className="print-hide" style={{fontSize:11,color:"#94a3b8"}}>{r.book_id}</div></>,fmtTime(r.borrowed_at),fmtTime(r.returned_at),<span className={`status ${r.status==="Dipinjam"?"dipinjam":"tersedia"}`}>{r.status}</span>]
    :tab==="kunjungan"?[<><b>{r.name}</b>{r.pending&&<PendingTag testId={`report-pending-${r.id}`}/>}<div className="print-hide" style={{fontSize:11,color:"#94a3b8"}}>{r.kind==="tamu"?"Tamu":`Anggota · ${r.student_id||r.member_id}`}</div></>,r.kind==="tamu"?(r.origin||"-"):r.class_name,r.purpose||"-",fmtTime(r.check_in),r.check_out?fmtClock(r.check_out):"Masih di dalam",fmtDur(r.duration_min),r.check_out?<span className={`status ${r.checkout_type==="otomatis"?"dipinjam":"keluar"}`}>{OUT_LABEL[r.checkout_type]||"Keluar"}</span>:<span className="status tersedia">Di dalam</span>]
    :tab==="masuk"?[i+1,<b>{r.title}</b>,r.author||"-",`${r.quantity||0} eks`,r.source||"-",fmtDate(r.date)]
    :[<b>{r.title}</b>,<>{r.code}{r.detail&&r.detail!==r.code?` · ${r.detail}`:""}{r.reported_by?<div style={{fontSize:11,color:"#94a3b8"}}>Pelapor: {r.reported_by}</div>:null}</>,<>{fmtDate(r.date)}{r.found_at?<div style={{fontSize:11,color:"#15803d"}}>Ditemukan {fmtDate(r.found_at)}</div>:null}</>,<span className={`status ${r.status==="Hilang"?"hilang":"ditemukan"}`}>{r.status}</span>];
  const tabs=[["ringkasan","Ringkasan & grafik","report-overview-tab"],["transaksi","Transaksi","report-transactions-tab"],["masuk","Buku masuk","report-incoming-tab"],["hilang","Buku hilang","report-missing-tab"],["kunjungan","Pengunjung","report-visits-tab"],["statistik","Statistik & persentase","report-stats-tab"],["peringkat","Peringkat rajin berkunjung","report-leaderboard-tab"],["peringkat-pinjam","Peringkat rajin meminjam","report-loan-leaderboard-tab"]];
  const vMembers=rows.filter(r=>r.kind==="anggota").length; const pct=(n)=>rows.length?`${((n/rows.length)*100).toFixed(1)}%`:"0%";
  return <><div className="print-header"><img src={settings?.school_logo||SCHOOL_LOGO} alt="Logo sekolah"/><div><b>PERPUSTAKAAN SMA NEGERI 1 ABUNG TENGAH</b><small>Jln Raya Subik, Desa Pekurun Selatan, Kec. Abung Tengah</small><span className="print-title">Laporan {tabs.find(t=>t[0]===tab)?.[1]}{["statistik","peringkat","peringkat-pinjam","ringkasan"].includes(tab)?"":` · ${periodLabel}`}</span><small>Dicetak {fmtDate(now)}</small></div><img src={settings?.library_logo||LIBRARY_LOGO} alt="Logo perpustakaan"/></div>
  <div className="report-bar"><div className="report-tabs">{tabs.map(([k,l,tid])=><button key={k} data-testid={tid} className={tab===k?"active":""} onClick={()=>setTab(k)}>{l}</button>)}{!["statistik","peringkat","peringkat-pinjam","ringkasan"].includes(tab)&&<div className="period-select"><button data-testid="period-all" className={period==="semua"?"active":""} onClick={()=>setPeriod("semua")}>Semua</button><button data-testid="period-daily" className={period==="harian"?"active":""} onClick={()=>setPeriod("harian")}>Harian</button><button data-testid="period-monthly" className={period==="bulanan"?"active":""} onClick={()=>setPeriod("bulanan")}>Bulanan</button></div>}</div></div>
  {tab==="ringkasan"&&<Suspense fallback={<ChartLoading/>}><ReportOverview notify={notify}/></Suspense>}
  {tab==="statistik"&&<Suspense fallback={<ChartLoading/>}><VisitStats download={download} downloading={downloading}/></Suspense>}
  {tab==="peringkat"&&<Leaderboard key="kunjungan" mode="admin" kind="kunjungan" download={download} downloading={downloading} audience={lbAudience} onAudience={setLbAudience}/>}{tab==="peringkat-pinjam"&&<Leaderboard key="pinjam" mode="admin" kind="pinjam" download={download} downloading={downloading} audience={lbAudience} onAudience={setLbAudience}/>}
  {tab==="transaksi"&&<div className="report-summary"><div><span>Total peminjaman</span><b data-testid="summary-total">{rows.length}</b><small>{periodLabel}</small></div><div><span>Masih dipinjam</span><b data-testid="summary-borrowed">{rows.filter(t=>t.status==="Dipinjam").length}</b><small>Perlu dikembalikan</small></div><div><span>Dikembalikan</span><b data-testid="summary-returned">{rows.filter(t=>t.status==="Dikembalikan").length}</b><small>Buku kembali</small></div></div>}
  {tab==="masuk"&&<div className="report-summary"><div><span>Penerimaan</span><b data-testid="summary-incoming-batches">{rows.length}</b><small>{periodLabel}</small></div><div><span>Total eksemplar</span><b data-testid="summary-incoming-qty">{rows.reduce((a,r)=>a+(r.quantity||0),0)}</b><small>dari {totalIn} sepanjang waktu</small></div><div><span>Sumber terbanyak</span><b style={{fontSize:18}}>{Object.entries(rows.reduce((a,r)=>{a[r.source||"-"]=(a[r.source||"-"]||0)+r.quantity;return a},{})).sort((a,b)=>b[1]-a[1])[0]?.[0]||"-"}</b><small>berdasarkan eksemplar</small></div></div>}
  {tab==="hilang"&&<div className="report-summary"><div><span>Laporan hilang</span><b data-testid="summary-missing">{rows.length}</b><small>{periodLabel}</small></div><div><span>Masih hilang</span><b>{rows.filter(r=>r.status==="Hilang").length}</b><small>dari {stillLost} total</small></div><div><span>Ditemukan kembali</span><b>{rows.filter(r=>r.status==="Ditemukan").length}</b><small>Dipulihkan ke koleksi</small></div></div>}
  {tab==="kunjungan"&&<OfflineBar testId="offline-bar-visit-report" kinds={["visit-"]}/>}
  {tab==="kunjungan"&&<div className="report-summary"><div><span>Total pengunjung</span><b data-testid="summary-visits">{rows.length}</b><small>{periodLabel}</small></div><div><span>Anggota</span><b data-testid="summary-visit-members">{vMembers}</b><small>{pct(vMembers)} dari pengunjung</small></div><div><span>Tamu</span><b data-testid="summary-visit-guests">{rows.length-vMembers}</b><small>{pct(rows.length-vMembers)} dari pengunjung</small></div></div>}
  {!["statistik","peringkat","peringkat-pinjam","ringkasan"].includes(tab)&&<div className="panel table-panel"><div className="panel-title"><div><p className="eyebrow">LAPORAN {tab.toUpperCase()}</p><h3>{tab==="transaksi"?"Riwayat peminjaman & pengembalian":tab==="masuk"?"Penerimaan koleksi baru":tab==="kunjungan"?"Buku tamu: masuk & keluar":"Daftar buku hilang"}</h3></div><div className="download-row"><PrintButton/><button className="secondary" data-testid="download-pdf-button" onClick={()=>download("pdf")} disabled={!!downloading}><Download size={16}/> {downloading==="pdf"?"Menyiapkan...":"PDF"}</button><button className="secondary" data-testid="download-xlsx-button" onClick={()=>download("xlsx")} disabled={!!downloading}><FileSpreadsheet size={16}/> {downloading==="xlsx"?"Menyiapkan...":"Excel"}</button>{canPurge&&<button className="secondary purge-open print-hide" data-testid="open-report-purge-button" onClick={()=>setPurgeOpen(true)}><Trash2 size={16}/> {picked.length?`Hapus (${picked.length})`:"Hapus laporan"}</button>}</div></div>
  <div className="table-wrap"><table><thead><tr>{canPurge&&(()=>{const ok=rows.filter(r=>!purgeLocked(tab,r)).map(r=>r.id);const all=ok.length>0&&ok.every(id=>picked.includes(id));return <th className="purge-col print-hide"><input type="checkbox" aria-label="Pilih semua" data-testid="purge-select-all" checked={all} disabled={!ok.length} onChange={()=>setPicked(all?[]:ok)}/></th>})()}{heads.map((h,j)=><th key={h} className={tab==="kunjungan"&&j===heads.length-1?"print-hide":undefined}>{h}</th>)}</tr></thead><tbody><ShowMore items={rows} colSpan={heads.length+(canPurge?1:0)}>{(vis)=>vis.map((r,i)=><tr key={r.id||i} data-testid={`report-row-${r.id||i}`}>{canPurge&&<td className="purge-col print-hide"><input type="checkbox" aria-label="Pilih baris" data-testid={`purge-select-${r.id}`} disabled={purgeLocked(tab,r)||!!r.pending} title={purgeLocked(tab,r)?(tab==="transaksi"?"Buku masih dipinjam":"Pengunjung masih di dalam"):undefined} checked={picked.includes(r.id)} onChange={()=>setPicked(p=>p.includes(r.id)?p.filter(x=>x!==r.id):[...p,r.id])}/></td>}{cells(r,i).map((c,j)=><td key={j} className={tab==="kunjungan"&&j===heads.length-1?"print-hide":undefined}>{c}</td>)}</tr>)}</ShowMore>{rows.length===0&&<tr><td colSpan={heads.length+(canPurge?1:0)} style={{textAlign:"center",padding:30,color:"#94a3b8"}} data-testid="report-empty">Belum ada data pada periode ini</td></tr>}</tbody></table></div></div>}{purgeOpen&&<ReportPurge tab={tab} selectedIds={picked} close={()=>setPurgeOpen(false)} notify={notify} onDone={()=>{setPicked([]);reload?.();setVisitsTick(t=>t+1)}}/>}<PrintSignature date={fmtDate(now)}/></>
}

// Router utama ada di Root.js (halaman admin dimuat terpisah)
export { StaffApp };
export default StaffApp;
